@Composable
fun ParameterWheelBox(
    label: String,
    value: String,
    options: List<String>,
    isActive: Boolean,
    height: androidx.compose.ui.unit.Dp,
    accentColor: Color,
    onValueChange: (String) -> Unit,
    onActivate: () -> Unit,
    modifier: Modifier,
    unit: String = ""
) {
    Column(modifier = modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Text(label, color = TextGray, fontSize = 9.sp, fontWeight = FontWeight.Bold)
        Spacer(Modifier.height(4.dp))
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(height)
                .clip(RoundedCornerShape(8.dp))
                .background(Color(0xFF0F151B))
                .border(1.dp, if (isActive) accentColor else Color.White.copy(alpha = 0.05f), RoundedCornerShape(8.dp))
                .clickable { onActivate() },
            contentAlignment = Alignment.Center
        ) {
            Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                if (isActive) {
                    WheelPickerScrollShared(
                        options = options,
                        currentValue = value,
                        onValueChange = onValueChange,
                        unit = unit,
                        containerHeight = height
                    )
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .border(1.dp, accentColor.copy(alpha = 0.5f), RoundedCornerShape(8.dp))
                    )
                } else {
                    Text(
                        text = "$value$unit",
                        color = Color.White,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center
                    )
                }
            }
        }
    }
}
